import type { H3Event } from "../event.ts";
import { HTTPError } from "../error.ts";
import { decodePreservingSeparators, withoutTrailingSlash } from "./internal/path.ts";
import { isCanonicalPath } from "./path.ts";
import { getType, getExtension } from "./internal/mime.ts";
import { isCacheMatch } from "./internal/cache.ts";
import { HTTPResponse } from "../response.ts";

export interface StaticAssetMeta {
  type?: string;
  etag?: string;
  mtime?: number | string | Date;
  size?: number;
  encoding?: string;
}

export interface ServeStaticOptions {
  /**
   * This function should resolve asset meta.
   *
   * **Security:** The `id` keeps encoded separators (`%2f`, `%5c`)
   * percent-encoded. Decoding them here re-introduces separators and defeats
   * the traversal normalization done by `serveStatic`. See {@link serveStatic}.
   */
  getMeta: (id: string) => StaticAssetMeta | undefined | Promise<StaticAssetMeta | undefined>;

  /**
   * This function should resolve asset content.
   *
   * **Security:** As with `getMeta`, the `id` must not be decoded before
   * resolving the asset. See {@link serveStatic}.
   */
  getContents: (id: string) => BodyInit | null | undefined | Promise<BodyInit | null | undefined>;

  /**
   * Headers to set on the response
   */
  headers?: HeadersInit;

  /**
   * Map of supported encodings (compressions) and their file extensions.
   *
   * Each extension will be appended to the asset path to find the compressed version of the asset.
   *
   * @example { gzip: ".gz", br: ".br" }
   */
  encodings?: Record<string, string>;

  /**
   * Default index file to serve when the path is a directory
   *
   * @default ["/index.html"]
   */
  indexNames?: string[];

  /**
   * When set to true, the function will not throw 404 error when the asset meta is not found or meta validation failed
   */
  fallthrough?: boolean;

  /**
   * Custom MIME type resolver function
   * @param ext - File extension including dot (e.g., ".css", ".js")
   */
  getType?: (ext: string) => string | undefined;
}

/**
 * Dynamically serve static assets based on the request path.
 *
 * **Security — path traversal:** `serveStatic` resolves `.`/`..` segments but
 * deliberately keeps encoded separators (`%2f`, `%5c`) percent-encoded in the
 * `id` it passes to `getMeta`/`getContents`, exactly as `event.url.pathname`
 * does. The `id` therefore has the same segment structure the router and
 * pathname-scoped `use()` guards matched on: `/private%5cx` stays one opaque
 * segment and cannot be served as `/private/x` past a `use("/private/**")`
 * guard. Resolve the `id` against your asset root as an opaque string — a
 * backend that decodes it re-introduces separators and re-opens the hole.
 *
 * A **non-canonical pathname is not served** (404, or falls through when
 * `fallthrough` is set): more than one leading separator (`//private/x`,
 * `/\\private/x`) or a dot segment that survived URL canonicalization, which
 * means one spelled with `%25`-nested escapes (`/pub/%252e%252e/private/x`).
 * Both dispatch to a catch-all route while missing a narrower
 * `use("/private/**")` guard, and the only `id` `serveStatic` could build from
 * them resolves back into the guarded path. Assets are reachable under their
 * canonical spelling — the one routing and `use()` guards match on — only.
 *
 * Everything else is decoded once for the on-disk lookup, so a file's real name
 * reaches the backend: `/50%25.png` → `/50%.png`, `/a%20b` → `/a b`, and one
 * `%25` level is peeled off a nested separator (`/a%252fb` → `/a%2fb`, still a
 * literal `%2f`, never a boundary). RFC 3986's reserved set stays encoded, so an
 * `id` can never grow a `?` or `#` that would truncate it in a URL.
 *
 * Two things `serveStatic` cannot enforce for filesystem-backed assets:
 * **case-insensitive filesystems** (macOS, Windows) need both sides of any
 * allow/deny check case-folded (otherwise `/SECRET.env` slips past a check for
 * `/secret.env`), and **symlinks** need the resolved path re-asserted against
 * the asset root after following links (e.g. `realpath(target)`).
 *
 * **Range:** a single byte range (`bytes=a-b`, `bytes=a-`, `bytes=-n`) is served
 * as `206`, and one that covers no byte as `416`. Any other `Range` (multiple
 * ranges, another unit, invalid syntax, or an `If-Range` that does not match) is
 * ignored and the full asset is served. Assets with a known `size` advertise
 * `accept-ranges: bytes`.
 */
export async function serveStatic(
  event: H3Event,
  options: ServeStaticOptions,
): Promise<HTTPResponse | undefined> {
  if (options.headers) {
    const entries = Array.isArray(options.headers)
      ? options.headers
      : typeof options.headers.entries === "function"
        ? options.headers.entries()
        : Object.entries(options.headers);
    for (const [key, value] of entries) {
      event.res.headers.set(key, value);
    }
  }

  if (event.req.method !== "GET" && event.req.method !== "HEAD") {
    if (options.fallthrough) {
      return;
    }
    event.res.headers.set("allow", "GET, HEAD");
    throw new HTTPError({ status: 405 });
  }

  // The id has to keep the segment structure dispatch matched on, so the one
  // thing it must never do is *rewrite* the pathname. `isCanonicalPath` rejects
  // exactly the inputs `resolveDotSegments` would rewrite rather than pass
  // through — a leading `[/\\]` run, a `\`, and a dot segment at any
  // `%25`-nesting depth — and each rewrite re-spells the request into a path the
  // router never saw:
  //   - `//private/x` misses a `use("/private/**")` guard (a literal
  //     `startsWith`, matching rou3) while a catch-all static route still
  //     matches; clamping the run to a single `/` for the lookup then serves the
  //     guarded asset unauthenticated.
  //   - `/pub/%252e%252e/private/x` is four opaque segments to `~findRoute` and
  //     to that same guard. Canonicalization decodes `%2e` (so the URL parser
  //     resolves `/pub/%2e%2e/private/x` before anything matches on it) but never
  //     `%25`, so a `%25`-nested spelling is *meant* to stay opaque; resolving
  //     those dots here walks the id back to the guarded `/private/x`.
  // Same class of hole as the `%5c` peel below, so same answer: refuse, rather
  // than serve a second, cache- and WAF-invisible spelling. Assets stay reachable
  // under their canonical spelling — the one the router sees — only.
  if (!isCanonicalPath(event.url.pathname)) {
    if (options.fallthrough) {
      return;
    }
    throw new HTTPError({ status: 404 });
  }

  // The path is canonical per the check above, so there is no traversal left to
  // resolve — the pathname *is* its own resolved form. All that remains is to
  // peel one `%25` level for the on-disk lookup (guarded: malformed `%` falls
  // back to the still-encoded pathname).
  //
  // The peel must never turn an encoded separator into a real one. `decodeURI`
  // holds back `%2f` (RFC 3986 reserved) but *not* `%5c`, which it decodes to
  // `\` — and `/private%5cx` is one opaque segment to `~findRoute` and to a
  // `use("/private/**")` guard, so a backend resolving `\` would read it as the
  // guarded `/private/x`. `decodePreservingSeparators` keeps both encoded, so the
  // id keeps the segment structure routing matched on.
  //
  // `nested: false` because this is a single decode: one `%25` level off `%252f`
  // leaves a literal `%2f`, not a separator, so filenames containing `%2f` stay
  // addressable. `decodeURI` (not `decodeURIComponent`) keeps `%23`/`%3f`
  // encoded, so a URL-composing backend cannot grow a truncating `#`/`?`.
  //
  // Re-checked rather than re-resolved: with no separator introduced there is no
  // new segment boundary, so a dot segment the peel reveals (one `%25` level off
  // `%252e`) can only be one the pathname already carried at a deeper nesting —
  // refused above. Resolving one here is precisely what would re-spell the id.
  const resolvedId = withoutTrailingSlash(event.url.pathname);
  let originalId = resolvedId;
  if (resolvedId.includes("%")) {
    try {
      const decodedId = decodePreservingSeparators(resolvedId, {
        decode: decodeURI,
        nested: false,
      });
      if (isCanonicalPath(decodedId)) {
        originalId = withoutTrailingSlash(decodedId);
      }
    } catch {
      // Malformed escape (e.g. a trailing `%`): keep the still-encoded
      // `resolvedId` already assigned to `originalId` above.
    }
  }

  const acceptEncodings = parseAcceptEncoding(
    event.req.headers.get("accept-encoding") || "",
    options.encodings,
  );

  let id = originalId;
  // The asset `id` stands for: the same path without a precompressed
  // variant's encoding extension.
  let assetId = originalId;
  let meta: StaticAssetMeta | undefined;

  const _ids = idSearchPaths(originalId, acceptEncodings, options.indexNames || ["/index.html"]);

  for (const _id of _ids) {
    const _meta = await options.getMeta(_id.id);
    if (_meta) {
      meta = _meta;
      id = _id.id;
      assetId = _id.assetId;
      break;
    }
  }

  if (!meta) {
    if (options.fallthrough) {
      return;
    }
    throw new HTTPError({ statusCode: 404 });
  }

  // The chosen variant depends on `accept-encoding` whenever encodings are
  // configured, including when the unencoded file is served. Set only once an
  // asset is found so a fallthrough does not leak it to the next handler.
  if (options.encodings && Object.keys(options.encodings).length > 0) {
    const vary = event.res.headers.get("vary") || "";
    if (!/(?:^|,)\s*(?:\*|accept-encoding)\s*(?:,|$)/i.test(vary)) {
      event.res.headers.append("vary", "accept-encoding");
    }
  }

  let mtimeDate: Date | undefined;
  if (meta.mtime) {
    mtimeDate = new Date(meta.mtime);
    // Truncate to whole seconds to match HTTP date precision, so a client
    // echoing our `last-modified` in `if-modified-since` still matches.
    mtimeDate.setMilliseconds(0);

    if (!event.res.headers.get("last-modified")) {
      event.res.headers.set("last-modified", mtimeDate.toUTCString());
    }
  }

  if (meta.etag && !event.res.headers.has("etag")) {
    event.res.headers.set("etag", meta.etag);
  }

  if (isCacheMatch(event.req.headers, { etag: meta.etag, lastModified: mtimeDate })) {
    return new HTTPResponse(null, {
      status: 304,
      statusText: "Not Modified",
    });
  }

  if (!event.res.headers.get("content-type")) {
    if (meta.type) {
      event.res.headers.set("content-type", meta.type);
    } else {
      // `/app.js.gz` is still `text/javascript`: resolve the requested asset's
      // type, not the extension of its precompressed variant.
      const ext = getExtension(assetId);
      const type = ext ? (options.getType?.(ext) ?? getType(ext)) : undefined;
      if (type) {
        event.res.headers.set("content-type", type);
      }
    }
  }

  if (meta.encoding && !event.res.headers.get("content-encoding")) {
    event.res.headers.set("content-encoding", meta.encoding);
  }

  if (meta.size !== undefined && meta.size > 0 && !event.res.headers.get("content-length")) {
    event.res.headers.set("content-length", meta.size + "");
  }

  if (typeof meta.size === "number") {
    event.res.headers.set("accept-ranges", "bytes");
  }

  // Range is evaluated after the 304 above, so a matching precondition wins.
  // Headers are written to `event.res` (not only to the response) so they take
  // precedence over the full-size `content-length` set above.
  const range = event.req.headers.get("range");
  if (
    range &&
    typeof meta.size === "number" &&
    ifRangeMatches(event.req.headers.get("if-range"), event.res.headers)
  ) {
    const result = parseRange(range, meta.size);
    if (result.type === "unsatisfiable") {
      event.res.headers.set("content-range", `bytes */${meta.size}`);
      event.res.headers.set("content-length", "0");
      return new HTTPResponse(null, { status: 416 });
    }
    if (result.type === "partial") {
      const { start, end } = result;
      const contents = event.req.method === "HEAD" ? null : await options.getContents(id);
      if (event.req.method === "GET" && !contents) {
        // No body to slice: same as the full response below.
        return new HTTPResponse(null, { status: 200 });
      }
      event.res.headers.set("content-range", `bytes ${start}-${end}/${meta.size}`);
      event.res.headers.set("content-length", String(end - start + 1));
      return new HTTPResponse(
        contents ? await sliceContents(contents, start, end) : null,
        { status: 206 },
      );
    }
  }

  if (event.req.method === "HEAD") {
    return new HTTPResponse(null, { status: 200 });
  }

  const contents = await options.getContents(id);
  return new HTTPResponse(contents || null, { status: 200 });
}

// --- Internal Utils ---

// `qvalue` grammar (RFC 9110 section 12.4.2).
const WEIGHT_RE = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/;

/**
 * Resolve the configured encoding extensions a request accepts, most preferred first.
 *
 * Coding names are case-insensitive, `q=0` means "not acceptable", `*` matches
 * any coding not listed explicitly and equal weights keep header order, with
 * explicitly listed codings ahead of `*` matches (RFC 9110 section 12.5.3).
 */
function parseAcceptEncoding(header?: string, encodingMap?: Record<string, string>): string[] {
  if (!encodingMap || !header) {
    return [];
  }
  const extensions = new Map<string, string>();
  for (const [name, ext] of Object.entries(encodingMap)) {
    extensions.set(normalizeCoding(name), ext);
  }
  // Coding -> weight, in header order. The first occurrence of a coding wins.
  const weights = new Map<string, number>();
  let wildcard: number | undefined;
  for (const part of header.split(",")) {
    const [rawName = "", ...params] = part.split(";");
    const name = normalizeCoding(rawName);
    if (name !== "*" && !extensions.has(name)) {
      continue;
    }
    const qParam = params.find((p) => /^\s*q\s*=/i.test(p));
    const qValue = qParam?.slice(qParam.indexOf("=") + 1).trim();
    // An unparsable weight drops the coding: identity is always a safe fallback,
    // while guessing `1` could force a coding the client tried to refuse.
    const q = qValue === undefined ? 1 : WEIGHT_RE.test(qValue) ? Number(qValue) : 0;
    if (name === "*") {
      wildcard ??= q;
    } else if (!weights.has(name)) {
      weights.set(name, q);
    }
  }
  if (wildcard) {
    for (const name of extensions.keys()) {
      if (!weights.has(name)) {
        weights.set(name, wildcard);
      }
    }
  }
  const accepted = [...weights]
    .filter(([, q]) => q > 0)
    .sort((a, b) => b[1] - a[1])
    .map(([name]) => extensions.get(name)!);
  return [...new Set(accepted)];
}

/** Lowercase a coding name and resolve the `x-gzip` / `x-compress` aliases (RFC 9110 section 8.4.1). */
function normalizeCoding(name: string): string {
  const coding = name.trim().toLowerCase();
  return coding === "x-gzip" || coding === "x-compress" ? coding.slice(2) : coding;
}

function idSearchPaths(id: string, encodings: string[], indexNames: string[]) {
  const ids: { id: string; assetId: string }[] = [];

  for (const suffix of ["", ...indexNames]) {
    const assetId = `${id}${suffix}`;
    for (const encoding of [...encodings, ""]) {
      ids.push({ id: `${assetId}${encoding}`, assetId });
    }
  }

  return ids;
}

import { beforeEach, describe, it, expect, vi } from "vitest";
import { H3, serveStatic, type ServeStaticOptions } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("serve static", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => (id.includes("404") ? undefined : `asset:${id}`)),
      getMeta: vi.fn((id) =>
        id.includes("404")
          ? undefined
          : {
              type: "text/plain",
              encoding: "utf8",
              etag: "w/123",
              mtime: 1_700_000_000_000,
              path: id,
              size: `asset:${id}`.length,
            },
      ),
      indexNames: ["/index.html"],
      encodings: { gzip: ".gz", br: ".br" },
      headers: {
        "cache-control": "public, max-age=86400",
      },
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  const expectedHeaders = {
    "content-type": "text/plain",
    etag: "w/123",
    "content-encoding": "utf8",
    "last-modified": new Date(1_700_000_000_000).toUTCString(),
    vary: "accept-encoding",
    "cache-control": "public, max-age=86400",
  };

  it("Can serve asset (GET)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Sets vary when a single encoding is accepted", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(res.headers.get("vary")).toBe("accept-encoding");
  });

  it("Keeps existing vary values", async () => {
    t.app.all("/cors/**", (event) => {
      event.res.headers.set("vary", "origin");
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { gzip: ".gz" },
      });
    });
    const res = await t.fetch("/cors/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBe("origin, accept-encoding");
  });

  it("Sets vary when no encoding is accepted", async () => {
    // Explicit `identity`: node's fetch adds `accept-encoding: gzip, deflate` when unset.
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "identity" },
    });
    expect(await res.text()).toBe("asset:/test.png");
    expect(res.headers.get("vary")).toBe("accept-encoding");
  });

  it("Does not set vary without configured encodings", async () => {
    t.app.all("/plain/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
      });
    });
    const res = await t.fetch("/plain/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBeNull();
  });

  it("Does not duplicate vary values", async () => {
    for (const [i, vary] of ["Accept-Encoding", "origin,accept-encoding", "*"].entries()) {
      t.app.all(`/dedupe${i}/**`, (event) => {
        event.res.headers.set("vary", vary);
        return serveStatic(event, {
          getContents: (id) => `asset:${id}`,
          getMeta: (id) => ({ type: "text/plain", path: id }),
          encodings: { gzip: ".gz" },
        });
      });
      const res = await t.fetch(`/dedupe${i}/test.png`, {
        headers: { "accept-encoding": "gzip" },
      });
      expect(res.headers.get("vary")).toBe(vary);
    }
  });

  it("Matches encodings with q-values and any case", async () => {
    for (const [acceptEncoding, expected] of [
      ["gzip;q=1.0", "asset:/test.png.gz"],
      ["GZIP", "asset:/test.png.gz"],
      ["br ; q=1", "asset:/test.png.br"],
      // Preferred by weight, not by header order.
      ["gzip;q=0.5, br;q=0.8", "asset:/test.png.br"],
      // Equal weights keep header order.
      ["br, gzip", "asset:/test.png.br"],
      // `q=0` means "not acceptable".
      ["gzip;q=0, br;q=0.000", "asset:/test.png"],
      ["gzip;q=0", "asset:/test.png"],
      // A coding with an unparsable weight is dropped (identity is always safe).
      ["gzip;q=0invalid, br;q=0.5", "asset:/test.png.br"],
      ["gzip;q=0.0001", "asset:/test.png"],
      ["gzip;q=-1", "asset:/test.png"],
      ['gzip;q="0"', "asset:/test.png"],
      ["br;q=0.001, gzip;q=0.0010", "asset:/test.png.br"],
      // `x-gzip` is an alias of `gzip`.
      ["X-GZIP", "asset:/test.png.gz"],
      // `*` matches any coding not listed explicitly.
      ["*", "asset:/test.png.gz"],
      ["gzip;q=0, *", "asset:/test.png.br"],
      ["br;q=0.5, *;q=0.8", "asset:/test.png.gz"],
      ["*;q=0", "asset:/test.png"],
      // Explicitly listed codings win ties with `*` matches.
      ["*, br", "asset:/test.png.br"],
      // The first occurrence of a coding wins.
      ["gzip;q=0, gzip", "asset:/test.png"],
    ]) {
      const res = await t.fetch("/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Ignores inherited object keys in accept-encoding", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "constructor, __proto__, toString" },
    });
    expect(await res.text()).toBe("asset:/test.png");
  });

  it("Normalizes configured encoding names", async () => {
    t.app.all("/aliases/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { GZIP: ".gz", "x-compress": ".Z" },
      });
    });
    for (const [acceptEncoding, expected] of [
      ["gzip", "asset:/aliases/test.png.gz"],
      ["compress", "asset:/aliases/test.png.Z"],
      ["x-compress", "asset:/aliases/test.png.Z"],
    ]) {
      const res = await t.fetch("/aliases/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("Handles cache (if-modified-since) for sub-second mtime", async () => {
    // mtime with millisecond precision. The `last-modified` header the server
    // emits is truncated to whole seconds (HTTP-date granularity), so a client
    // echoing that exact value in `if-modified-since` must still get a 304.
    const subSecondOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `asset:${id}`),
      getMeta: vi.fn((id) => ({
        type: "text/plain",
        mtime: 1_700_000_000_500, // 500ms past the whole second
        path: id,
        size: `asset:${id}`.length,
      })),
    };
    t.app.all("/subsec/**", (event) => serveStatic(event, subSecondOptions));

    // The exact value the server reports in `last-modified`.
    const lastModified = new Date(1_700_000_000_500).toUTCString();
    const res = await t.fetch("/subsec/test.png", {
      headers: { "if-modified-since": lastModified },
